                page.Visible=true;navbtn.BackgroundColor3=C.selected;navTexts[info.key].TextColor3=C.pink;recolorIcon(info.key,C.pink);title.Text=info.name
            end)
        end
    end
    local home=text(pages.home,"Функции перенесены из исходного меню.\nВыберите раздел слева.\n\nНастройки функций открываются внутри соответствующих пунктов.\nКлавишу открытия можно изменить в профиле.\nЗакрытие окна возвращает старое меню.",
        UDim2.fromOffset(0,0),UDim2.new(1,-10,0,160),15,C.muted)
    home.TextWrapped=true;home.TextYAlignment=Enum.TextYAlignment.Top;home.LayoutOrder=1
    local bindCard=make("Frame",{LayoutOrder=1,Size=UDim2.new(1,-10,0,130),
        BackgroundColor3=C.sidebar,BorderSizePixel=0},pages.profile);corner(bindCard,14)
    text(bindCard,"Клавиша меню",UDim2.fromOffset(18,14),UDim2.new(1,-36,0,24),17,C.white,Enum.Font.GothamBold)
    text(bindCard,"Нажмите кнопку и выберите клавишу",UDim2.fromOffset(18,42),UDim2.new(1,-36,0,18),12,C.muted)
    local keyButton=make("TextButton",{Position=UDim2.fromOffset(18,72),Size=UDim2.fromOffset(140,38),
        BackgroundColor3=C.selected,Text=menuKey.Name,TextColor3=C.white,AutoButtonColor=false,
        Font=Enum.Font.GothamBold,TextSize=15,BorderSizePixel=0},bindCard);corner(keyButton,10)
    local keyStatus=text(bindCard,"По умолчанию: Home",UDim2.new(0,172,0,72),UDim2.new(1,-190,0,38),11,C.muted)
    local awaitingKey=false
    keyButton.MouseButton1Click:Connect(function()
        awaitingKey=true;keyButton.Text="Нажмите клавишу";keyStatus.Text="Esc — отменить"
    end)
    profileButton.MouseButton1Click:Connect(function()
        for _,p in pairs(pages) do p.Visible=false end
        for k,b in pairs(navs) do b.BackgroundColor3=C.sidebar;navTexts[k].TextColor3=C.muted;recolorIcon(k,C.muted) end
        pages.profile.Visible=true;title.Text="Профиль"
    end)
    -- Apply the palette to the original controls without replacing them or
    -- touching colour swatches / switch backgrounds that carry live state.
    local themed={}
    local function themeElement(obj)
        if restored or themed[obj] then return end
        themed[obj]=true
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            if obj.Text~="" then
                rememberStyle(obj,"TextColor3");rememberStyle(obj,"Font")
                local arrow=obj.Text=="▶" or obj.Text=="▼" or obj.Text=="▸" or obj.Text=="▾"
                obj.TextColor3=arrow and C.pink or C.white;obj.Font=Enum.Font.Gotham
            end
            if (obj:IsA("TextButton") or obj:IsA("TextBox")) and obj.Text~="" and obj.Text~="S"
                and obj.BackgroundTransparency<0.95 then
                rememberStyle(obj,"BackgroundColor3");obj.BackgroundColor3=C.selected
                if not obj:FindFirstChildWhichIsA("UICorner") then table.insert(decoration,corner(obj,6)) end
                local stroke=obj:FindFirstChildWhichIsA("UIStroke")
                if stroke then rememberStyle(stroke,"Color");stroke.Color=C.line end
            end
            -- A blank button with a Frame child is a slider track, not a toggle
            -- or a colour swatch. Keep its live value/position untouched.
            if obj:IsA("TextButton") and obj.Text=="" and obj.BackgroundTransparency<0.95 then
                local fill=obj:FindFirstChildWhichIsA("Frame")
                if fill and not fill:FindFirstChildWhichIsA("UIListLayout") then
                    rememberStyle(obj,"BackgroundColor3");obj.BackgroundColor3=C.selected
                    rememberStyle(fill,"BackgroundColor3");fill.BackgroundColor3=C.pink
                end
            end
        elseif obj:IsA("Frame") and obj.BackgroundTransparency<0.95 then
            local color=obj.BackgroundColor3
            local isDark=color.R<0.15 and color.G<0.15 and color.B<0.15
            local isRow=obj:FindFirstChildWhichIsA("TextLabel") or obj:FindFirstChildWhichIsA("TextButton") or obj:FindFirstChildWhichIsA("UIListLayout")
            if isDark and isRow and not (obj.Parent and obj.Parent:IsA("GuiButton")) then
                rememberStyle(obj,"BackgroundColor3");obj.BackgroundColor3=C.sidebar
            end
        elseif obj:IsA("ScrollingFrame") then
            rememberStyle(obj,"ScrollBarImageColor3");obj.ScrollBarImageColor3=C.border
        end
    end
    local function themeTree(root)
        themeElement(root)
        for _,obj in ipairs(root:GetDescendants()) do themeElement(obj) end
        table.insert(connections,root.DescendantAdded:Connect(function(obj)
            task.defer(function() if not restored and obj:IsDescendantOf(root) then pcall(themeElement,obj) end end)
        end))
    end
    -- Dropdown option menus live beside the old main window, not within the
    -- moved sections. Style only top-level popup groups with a direct scroller;
    -- their click callbacks and the original config remain untouched.
    local themedPopups={}
    local function themePopup(group)
        if restored or themedPopups[group] or group==main or not group:IsA("CanvasGroup") then return end
        local scroll=group:FindFirstChildWhichIsA("ScrollingFrame")
        if not scroll then return end
        themedPopups[group]=true
        rememberStyle(group,"BackgroundColor3");group.BackgroundColor3=C.sidebar
        for _,node in ipairs(group:GetDescendants()) do
            if node:IsA("Frame") and node.Parent==group and node.BackgroundTransparency<0.95 then
                rememberStyle(node,"BackgroundColor3");node.BackgroundColor3=C.sidebar
                local stroke=node:FindFirstChildWhichIsA("UIStroke")
                if stroke then rememberStyle(stroke,"Color");stroke.Color=C.border end
            end
        end
        themeTree(scroll)
        for _,option in ipairs(scroll:GetChildren()) do
            if option:IsA("TextButton") and option.Text~="" then
                if option.BackgroundTransparency>=0.95 then
                    rememberStyle(option,"BackgroundTransparency");option.BackgroundTransparency=0
                    rememberStyle(option,"BackgroundColor3");option.BackgroundColor3=C.sidebar
                    if not option:FindFirstChildWhichIsA("UICorner") then table.insert(decoration,corner(option,6)) end
                end
            end
        end
    end
    for _,child in ipairs(original:GetChildren()) do themePopup(child) end
    table.insert(connections,original.ChildAdded:Connect(function(child)
        task.defer(function() if not restored and child.Parent==original then pcall(themePopup,child) end end)
    end))
    local count={visual=0,movement=0,combat=0,other=0}
    local function place(section,key)
        local page=pages[key];count[key]=count[key]+1;local base=count[key]*2
        remember(section.head);remember(section.body)
        section.head.LayoutOrder=base;section.body.LayoutOrder=base+1
        section.head.Parent=page;section.body.Parent=page
        themeTree(section.body)
        -- Preserve the actual controls and their event handlers. The large headings
        -- open the original expandable groups; existing switches keep their state.
        rememberStyle(section.head,"BackgroundTransparency")
        section.head.BackgroundTransparency=1
        section.head.Size=UDim2.new(1,-8,0,62)
        for _,child in ipairs(section.head:GetChildren()) do
            if child:IsA("TextLabel") then
                for _,prop in ipairs({"TextColor3","TextSize","Font","Position","Size","TextXAlignment"}) do rememberStyle(child,prop) end
                local isArrow=child.Text=="▶" or child.Text=="▼" or child.Text=="▸" or child.Text=="▾"
                child.TextColor3=isArrow and C.pink or C.white
                child.TextSize=isArrow and 16 or 19;child.Font=Enum.Font.GothamBold
                child.Position=isArrow and UDim2.new(1,-30,0,12) or UDim2.fromOffset(8,6)
                child.Size=isArrow and UDim2.fromOffset(22,30) or UDim2.new(1,-55,0,27)
                child.TextXAlignment=isArrow and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
            end
        end
        local hint=text(section.head,"Нажмите, чтобы открыть функции и настройки",UDim2.fromOffset(8,35),
            UDim2.new(1,-48,0,18),12,C.muted)
        table.insert(decoration,hint)
    end
    for _,section in ipairs(vSections) do place(section,"visual") end
    for _,section in ipairs(mSections) do
        local name=section.name:lower();local key="other"
        if name=="movement" or name=="vaultables" then key="movement"
        elseif name=="aimbot" then key="combat" end
        place(section,key)
    end
    if settings then
        remember(settings);settings.Parent=pages.settings;settings.Size=UDim2.new(1,-8,0,360)
        settings.Position=UDim2.fromOffset(0,0);settings.LayoutOrder=1;settings.Visible=true
        themeTree(settings)
    else
        local msg=text(pages.settings,"Настройки исходного меню не найдены.",UDim2.fromOffset(0,0),UDim2.new(1,0,0,60),14,C.muted)
        msg.LayoutOrder=1
    end
    main.Visible=false
    -- Run after the default camera scripts so the cursor can be used while the
    -- menu is open. Restore the pre-menu mouse state if the bridge is destroyed.
    RunService:BindToRenderStep(MOUSE_STEP,Enum.RenderPriority.Camera.Value+1,function()
        if restored or not bridge.Parent then return end
        pcall(function()
            UserInputService.MouseBehavior=bridge.Visible and Enum.MouseBehavior.Default or Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled=bridge.Visible
        end)
    end)
    mouseStepBound=true
    -- The integrated VM temporarily suspends only its own legacy menu-key handler.
    -- This prevents the old menu from also opening on Home. restore() re-enables it.
    foxyLegacyHotkeyBlocked=true
    pages.home.Visible=true;navs.home.BackgroundColor3=C.selected;navTexts.home.TextColor3=C.pink;recolorIcon("home",C.pink)
    table.insert(connections,UserInputService.InputBegan:Connect(function(input,processed)
        if input.UserInputType~=Enum.UserInputType.Keyboard then return end
        if awaitingKey then
            if input.KeyCode==Enum.KeyCode.Escape then
                awaitingKey=false;keyButton.Text=menuKey.Name;keyStatus.Text="Изменение отменено";return
            end
            if input.KeyCode==Enum.KeyCode.Unknown then return end
            menuKey=input.KeyCode;awaitingKey=false;keyButton.Text=menuKey.Name;keyStatus.Text=storeKey(menuKey)
            return
        end
        if not processed and not UserInputService:GetFocusedTextBox() and input.KeyCode==menuKey then
            bridge.Visible=not bridge.Visible
        end
    end))
    print(string.format("[Foxy Bloom] Подключено разделов: визуалы %d, перемещение %d, прицел %d, другие %d. Настройки: %s.",
        count.visual,count.movement,count.combat,count.other,tostring(settings~=nil)))
end,function(e) return tostring(e) end)
if not ok then
    warn("[Foxy Bloom] Ошибка создания; восстанавливаю старое меню: "..tostring(err))
    restore();if bridge then pcall(function() bridge:Destroy() end) end
end

end)
return execute_vm(vm_function,{},pack_values(...))
